import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"命令与权限","description":"","frontmatter":{},"headers":[],"relativePath":"modules/cooking/commands.md","filePath":"modules/cooking/commands.md","lastUpdated":0}`),a={name:`modules/cooking/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="命令与权限" tabindex="-1">命令与权限 <a class="header-anchor" href="#命令与权限" aria-label="Permalink to “命令与权限”">​</a></h1><p>EmakiCooking 的主命令是 <code>/ecooking</code>，别名为 <code>/ec</code>。管理员主要用它重载工位配置、检查手持物/目标方块来源、重建工位索引和查看运行调试信息。</p><h2 id="命令列表" tabindex="-1">命令列表 <a class="header-anchor" href="#命令列表" aria-label="Permalink to “命令列表”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/ec help</code></td><td><code>emakicooking.use</code></td><td>显示帮助。</td></tr><tr><td><code>/ec reload</code></td><td><code>emakicooking.reload</code> 或 <code>emakicooking.admin</code></td><td>重载主配置、语言、工位、配方、GUI 与物品调整。</td></tr><tr><td><code>/ec inspect hand</code></td><td><code>emakicooking.inspect</code>、<code>emakicooking.use</code> 或 <code>emakicooking.admin</code></td><td>检查手持物来源和烹饪匹配情况。</td></tr><tr><td><code>/ec inspect block</code></td><td><code>emakicooking.inspect</code>、<code>emakicooking.use</code> 或 <code>emakicooking.admin</code></td><td>检查准星 6 格内目标方块的工位类型、方块状态、TileState、PDC/YAML 后端和索引状态。</td></tr><tr><td><code>/ec station reindex</code></td><td><code>emakicooking.admin</code></td><td>重建工位坐标索引，扫描 legacy YAML 与当前已加载区块中的 PDC 工位。</td></tr><tr><td><code>/ec convert-legacy [confirm]</code></td><td><code>emakicooking.admin</code></td><td>将配置中的旧扁平 matcher 键迁移为同级 <code>item_sources</code> + <code>matcher</code> 或嵌套角色节点；发酵桶 <code>inputs[]</code> 保留旧键以兼容持久化槽位身份。不带参数只预演，带 <code>confirm</code>（或 <code>--apply</code>）才写盘并保留备份。</td></tr><tr><td><code>/ec debug [status|on|off|player &lt;玩家&gt;|module &lt;模块&gt;]</code></td><td><code>emakicooking.debug</code> 或 <code>emakicooking.admin</code></td><td>输出运行时调试信息，见下方子命令说明。</td></tr></tbody></table><h2 id="营养命令" tabindex="-1">营养命令 <a class="header-anchor" href="#营养命令" aria-label="Permalink to “营养命令”">​</a></h2><p><code>/ec nutrition</code> 用于查询和管理玩家营养值。营养玩法说明见 <a href="./nutrition.html">营养系统</a>。</p><table tabindex="0"><thead><tr><th>命令</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td><code>/ec nutrition get [玩家] [类型]</code></td><td><code>emakicooking.nutrition.use</code>、<code>emakicooking.nutrition.admin</code> 或 <code>emakicooking.admin</code></td><td>查询营养值。不带类型列出全部类型的 <code>值 / 上限</code>；带类型返回单类型当前值。玩家可省略（默认查自己，控制台必须指定）。</td></tr><tr><td><code>/ec nutrition set &lt;玩家&gt; &lt;类型&gt; &lt;数值&gt;</code></td><td><code>emakicooking.nutrition.admin</code> 或 <code>emakicooking.admin</code></td><td>设置指定玩家某营养类型的值。</td></tr><tr><td><code>/ec nutrition add &lt;玩家&gt; &lt;类型&gt; &lt;数值&gt;</code></td><td><code>emakicooking.nutrition.admin</code> 或 <code>emakicooking.admin</code></td><td>增加指定玩家某营养类型的值。</td></tr><tr><td><code>/ec nutrition remove &lt;玩家&gt; &lt;类型&gt; &lt;数值&gt;</code></td><td><code>emakicooking.nutrition.admin</code> 或 <code>emakicooking.admin</code></td><td>减少指定玩家某营养类型的值。</td></tr></tbody></table><ul><li><code>set</code>、<code>add</code>、<code>remove</code> 需要四段参数齐全，目标玩家必须在线，数值写入后按类型 <code>min~max</code> 截断。</li><li>营养系统未启用时，营养命令会提示已禁用。</li></ul><h2 id="基础权限" tabindex="-1">基础权限 <a class="header-anchor" href="#基础权限" aria-label="Permalink to “基础权限”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakicooking.use</code></td><td>true</td><td>基础使用权限。</td></tr><tr><td><code>emakicooking.reload</code></td><td>op</td><td>重载配置。</td></tr><tr><td><code>emakicooking.inspect</code></td><td>op</td><td>检查物品或工位。</td></tr><tr><td><code>emakicooking.admin</code></td><td>op</td><td>管理员权限。</td></tr><tr><td><code>emakicooking.debug</code></td><td>op</td><td>调试权限。</td></tr></tbody></table><h2 id="工位权限" tabindex="-1">工位权限 <a class="header-anchor" href="#工位权限" aria-label="Permalink to “工位权限”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakicooking.station.chopping_board.use</code></td><td>true</td><td>使用砧板。</td></tr><tr><td><code>emakicooking.station.chopping_board.cut</code></td><td>true</td><td>执行砧板切割。</td></tr><tr><td><code>emakicooking.station.wok.use</code></td><td>true</td><td>使用炒锅。</td></tr><tr><td><code>emakicooking.station.wok.stir</code></td><td>true</td><td>翻炒。</td></tr><tr><td><code>emakicooking.station.wok.serve</code></td><td>true</td><td>出锅。</td></tr><tr><td><code>emakicooking.station.grinder.use</code></td><td>true</td><td>使用研磨机。</td></tr><tr><td><code>emakicooking.station.steamer.use</code></td><td>true</td><td>使用蒸锅。</td></tr><tr><td><code>emakicooking.station.steamer.fuel</code></td><td>true</td><td>为蒸锅添加燃料。</td></tr><tr><td><code>emakicooking.station.steamer.moisture</code></td><td>true</td><td>为蒸锅添加水分或湿度材料。</td></tr><tr><td><code>emakicooking.station.oven.use</code></td><td>true</td><td>使用烤炉。</td></tr><tr><td><code>emakicooking.station.oven.fuel</code></td><td>true</td><td>为烤炉添加燃料。</td></tr><tr><td><code>emakicooking.station.juicer.use</code></td><td>true</td><td>使用榨汁机。</td></tr><tr><td><code>emakicooking.station.juicer.press</code></td><td>true</td><td>执行压榨。</td></tr><tr><td><code>emakicooking.station.juicer.collect</code></td><td>true</td><td>盛取榨汁结果。</td></tr><tr><td><code>emakicooking.station.fermentation_barrel.use</code></td><td>true</td><td>使用发酵桶。</td></tr><tr><td><code>emakicooking.station.fermentation_barrel.start</code></td><td>true</td><td>开始发酵。</td></tr><tr><td><code>emakicooking.station.fermentation_barrel.collect</code></td><td>true</td><td>收取发酵结果。</td></tr></tbody></table><div class="important custom-block"><p class="custom-block-title custom-block-title-default">IMPORTANT</p><p>当前权限采用 <code>emakicooking.station.*</code> 形式。旧配置中如果存在简写权限，应迁移到上表格式。</p></div><h2 id="营养权限" tabindex="-1">营养权限 <a class="header-anchor" href="#营养权限" aria-label="Permalink to “营养权限”">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>emakicooking.nutrition.use</code></td><td>true</td><td>查询自己的营养值（<code>/ec nutrition get</code>）。</td></tr><tr><td><code>emakicooking.nutrition.admin</code></td><td>op</td><td>设置、增加、减少任意玩家营养值。</td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p><code>emakicooking.admin</code> 可覆盖全部营养操作。</p></div><h2 id="先用哪个命令" tabindex="-1">先用哪个命令 <a class="header-anchor" href="#先用哪个命令" aria-label="Permalink to “先用哪个命令”">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>先执行</th><th>目的</th></tr></thead><tbody><tr><td>改了工位、配方、GUI 或语言</td><td><code>/ec reload</code></td><td>重载 Cooking 运行配置。</td></tr><tr><td>材料、燃料或容器不匹配</td><td><code>/ec inspect hand</code></td><td>查看手持物被识别成什么物品来源。</td></tr><tr><td>工位方块、PDC 后端或索引异常</td><td><code>/ec inspect block</code></td><td>查看目标方块是否为 <code>TileState</code>、当前后端、PDC/YAML 状态和索引记录。</td></tr><tr><td>迁移旧 YAML、换方块或重启后工位缺失</td><td><code>/ec station reindex</code></td><td>重建 <code>data/stations/index/&lt;world&gt;.idx</code> 坐标索引。</td></tr><tr><td>工位监听或展示异常</td><td><code>/ec debug</code></td><td>查看运行时状态和调试输出。</td></tr></tbody></table><h2 id="常见操作" tabindex="-1">常见操作 <a class="header-anchor" href="#常见操作" aria-label="Permalink to “常见操作”">​</a></h2><h3 id="检查手持物来源" tabindex="-1">检查手持物来源 <a class="header-anchor" href="#检查手持物来源" aria-label="Permalink to “检查手持物来源”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec inspect hand</span></span></code></pre></div><p>用于确认手持物是否能被识别为配方输入、容器、燃料、工具或工位方块。排查自定义物品来源时优先使用该命令。</p><h3 id="检查目标工位方块" tabindex="-1">检查目标工位方块 <a class="header-anchor" href="#检查目标工位方块" aria-label="Permalink to “检查目标工位方块”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec inspect block</span></span></code></pre></div><p>用于查看准星 6 格内目标方块的工位类型、物品来源、<code>block_state</code>、<code>tile_state</code>、<code>storage_backend</code>、<code>pdc_state</code>、<code>indexed</code>、<code>index_backend</code> 和 <code>legacy_yaml</code>。大量工位服务器可用它确认锚点是否走 <code>BLOCK_PDC</code>，从而减少独立 YAML 文件 IO。</p><h3 id="重建工位坐标索引" tabindex="-1">重建工位坐标索引 <a class="header-anchor" href="#重建工位坐标索引" aria-label="Permalink to “重建工位坐标索引”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec station reindex</span></span></code></pre></div><p>用于扫描旧 YAML 状态和当前已加载区块中的 PDC 工位，重建 <code>data/stations/index/&lt;world&gt;.idx</code>。迁移旧数据、替换方块实体或发现 ChunkLoad 后工位未恢复时优先执行。</p><h3 id="重载烹饪配置" tabindex="-1">重载烹饪配置 <a class="header-anchor" href="#重载烹饪配置" aria-label="Permalink to “重载烹饪配置”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec reload</span></span></code></pre></div><p>重载后建议检查控制台输出。如果新增了工位方块、GUI 或配方目录，建议在测试服先验证状态保存与交互流程。</p><h3 id="调试运行状态" tabindex="-1">调试运行状态 <a class="header-anchor" href="#调试运行状态" aria-label="Permalink to “调试运行状态”">​</a></h3><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/ec debug</span></span>
<span class="line"><span>/ec debug status</span></span>
<span class="line"><span>/ec debug on</span></span>
<span class="line"><span>/ec debug off</span></span>
<span class="line"><span>/ec debug player &lt;玩家&gt;</span></span>
<span class="line"><span>/ec debug module &lt;模块&gt;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>子命令</th><th>说明</th></tr></thead><tbody><tr><td>不带参数 / <code>status</code></td><td>输出当前调试开关、被跟踪玩家和已开启模块。</td></tr><tr><td><code>on</code> / <code>off</code></td><td>全局开启或关闭调试输出。</td></tr><tr><td><code>player &lt;玩家&gt;</code></td><td>切换只跟踪该在线玩家；省略玩家名时列出可用模块。</td></tr><tr><td><code>module &lt;模块&gt;</code></td><td>切换单个模块的调试输出。EmakiCooking 可用模块：<code>recipe</code>、<code>stir</code>、<code>display</code>、<code>station</code>、<code>pdc</code>（另含 CoreLib 共享模块）。</td></tr></tbody></table><p>无法识别的子命令会回退为输出状态。适合排查工位监听、展示实体、配方匹配、持久化状态等问题。正式服长期排查时，建议配合控制台日志使用，避免玩家端信息过多。</p><h2 id="排查建议" tabindex="-1">排查建议 <a class="header-anchor" href="#排查建议" aria-label="Permalink to “排查建议”">​</a></h2><ul><li>工位无法使用：检查方块来源、工位权限和交互方式是否匹配。</li><li>工位状态或后端不确定：对准目标方块执行 <code>/ec inspect block</code>，确认 <code>tile_state</code>、<code>storage_backend</code>、<code>pdc_state</code>、<code>indexed</code> 和 <code>legacy_yaml</code>。</li><li>重启或区块加载后工位未恢复：先执行 <code>/ec station reindex</code> 重建索引，再观察控制台是否出现 <code>lost_block_entity_replaced</code> 或 mismatch 报告。</li><li>材料无法放入：检查 <code>input_rules.only_recipe_items</code>、配方目录和物品来源。</li><li>榨汁机无法盛取：检查流体容量是否达到容器 <code>serving_ml</code>，并确认玩家拥有 <code>emakicooking.station.juicer.collect</code>。</li><li>发酵桶无法开始：检查输入是否匹配配方、玩家是否拥有 <code>start</code> 权限。</li><li>烤炉不推进：检查火力是否处于配方要求区间，燃料是否生效。</li></ul>`,37)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};